def _origin(city):
    city = (city or '').strip()
    if not city:
        return ''
    if 'تهران' in city:
        return 'tehran'
    if 'قم' in city:
        return 'qom'
    if 'مهران' in city:
        return 'mehran'
    return 'transit'


