    rows = []
    for b in Booking.objects.filter(is_completed=True).exclude(status='cancelled').order_by('created_at', 'id'):
        count = max(1, b.passenger_count or 1)
        per = int(b.total_price or 0) // count
        paid = per if b.is_paid else 0
        origin = _origin(b.boarding_city)
        people = [(None, b.main_passenger_name or 'سرپرست', b.main_passenger_phone or '')]
        for i, c in enumerate(b.companions or []):
            name = c.get('name') or f"{c.get('firstName', '')} {c.get('lastName', '')}".strip()
            people.append((i, name or f'همراه {i + 1}', c.get('phone') or ''))
        for idx, name, phone in people:
            rows.append(LedgerRow(
                caravan_id=b.caravan_id, booking_id=b.id, companion_index=idx,
                full_name=name[:120], phone=phone, cost=per, paid=paid, origin=origin,
            ))
    LedgerRow.objects.bulk_create(rows)


